using System;using System.IO;using UnityEditor;using UnityEngine;
namespace AssetPipeline.Editor
{
 public static partial class CombatShaderAuthoring
 {
  [InitializeOnLoadMethod]static void CraterWatch(){EditorApplication.update+=()=>{if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(Stage+"CraterGraph.request"))return;File.Delete(Stage+"CraterGraph.request");try{Crater();Crater(true);File.WriteAllText(Stage+"crater_graph.json","{\"passed\":true}");}catch(Exception e){File.WriteAllText(Stage+"crater_graph.json",e.ToString());Debug.LogException(e);}};}
  static object Sample(string name,string reference,string path,float y,bool normal=false){var prop=Prop("Texture2DShaderProperty",name,reference,AssetDatabase.LoadAssetAtPath<Texture2D>(path),-900,y);var sample=Node("SampleTexture2DNode",-580,y);if(normal)GraphReflect.Set(sample,"textureType","Normal");Link(prop,0,sample,1);return sample;}
  static void Crater(bool pom=false)
  {
   graph=GraphReflect.New(SG+"GraphData");GraphReflect.Call(graph,"AddContexts");GraphReflect.Set(graph,"path","Game/VFX");var target=GraphReflect.New("UnityEditor.Rendering.Universal.ShaderGraph.UniversalTarget");GraphReflect.Call(target,"TrySetActiveSubTarget",GraphReflect.T("UnityEditor.Rendering.Universal.ShaderGraph.UniversalDecalSubTarget"));var data=GraphReflect.Get(GraphReflect.Get(target,"activeSubTarget"),"decalData");GraphReflect.Set(data,"affectsAlbedo",false);GraphReflect.Set(data,"affectsEmission",false);GraphReflect.Set(data,"affectsNormal",true);GraphReflect.Set(data,"affectsNormalBlend",true);GraphReflect.Set(data,"affectsMAOS",true);
   var targets=Array.CreateInstance(GraphReflect.T(SG+"Target"),1);targets.SetValue(target,0);string[] names={"NormalTS","NormalAlpha","Occlusion","MAOSAlpha","Metallic","Smoothness"};var descriptors=Array.CreateInstance(GraphReflect.T(SG+"BlockFieldDescriptor"),names.Length);for(int i=0;i<names.Length;i++)descriptors.SetValue(GraphReflect.Field((names[i]=="NormalAlpha"||names[i]=="MAOSAlpha")?"UnityEditor.Rendering.Universal.ShaderGraph.UniversalBlockFields+SurfaceDescription":SG+"BlockFields+SurfaceDescription",names[i]),i);GraphReflect.Call(graph,"InitializeOutputs",targets,descriptors);
   const string tex="Assets/Game/VFX/Combat/Textures/Crater/DrillCrater_1";var n=Sample("Crater Normal","_CraterNormal",tex+"_Normal.png",0,true);var ao=Sample("Crack Occlusion","_CraterAO",tex+"_AO.png",350);var mask=Sample("Projection Mask","_CraterMask",tex+"_Mask.png",700);var strength=Prop("Vector1ShaderProperty","Normal Strength","_NormalStrength",1f,-580,1000);var aoStrength=Prop("Vector1ShaderProperty","AO Strength","_AOIntensity",1f,-580,1200);var smooth=Prop("Vector1ShaderProperty","Cracked Surface Smoothness","_Smoothness",.15f,-150,1100);

   if(pom){var height=Prop("Texture2DShaderProperty","Height Map (white top)","_HeightMap",AssetDatabase.LoadAssetAtPath<Texture2D>(tex+"_Height.png"),-1500,-850);var amplitude=Prop("Vector1ShaderProperty","Depth in centimetres","_HeightAmplitudeCm",20f,-1500,-600);var steps=Prop("Vector1ShaderProperty","POM Steps","_POMSteps",16f,-1500,-400);var primitive=Prop("Vector2ShaderProperty","Primitive UV size (local metres)","_PrimitiveSize",new Vector4(1,1,0,0),-1500,-200);var uv=Node("UVNode",-1800,50);var march=Node("ParallaxOcclusionMappingNode",-950,-550);Link(height,0,march,2);Link(amplitude,0,march,4);Link(steps,0,march,5);Link(uv,0,march,6);Link(primitive,0,march,12);Link(march,1,n,2);Link(march,1,ao,2);Link(march,1,mask,2);}
   var originalUV=Node("UVNode",-900,1800);var edgeStart=Prop("Vector1ShaderProperty","Edge Fade Start","_EdgeFadeStart",.62f,-580,1800);var edgeEnd=Prop("Vector1ShaderProperty","Edge Fade End","_EdgeFadeEnd",.95f,-580,2000);var opacity=Prop("Vector1ShaderProperty","Crack Opacity","_CrackOpacity",1f,-580,1400);var f=Function("CraterSurface","Normal=normalize(float3(N.xy*Strength,max(.05,N.z)));Occlusion=lerp(1,AO,saturate(AOStrength));Opacity=Mask*CrackOpacity*(1-smoothstep(FadeStart,FadeEnd,length(UV*2-1)));",new[]{("N",(object)Vector3.forward),("Strength",(object)1f),("AO",(object)1f),("AOStrength",(object)1f),("Mask",(object)1f),("CrackOpacity",(object)1f),("UV",(object)Vector2.zero),("FadeStart",(object).62f),("FadeEnd",(object).95f)},new[]{("Normal",(object)Vector3.forward),("Occlusion",(object)1f),("Opacity",(object)1f)},-100,0);Link(n,0,f,0);Link(strength,0,f,1);Link(ao,4,f,2);Link(aoStrength,0,f,3);Link(mask,4,f,4);Link(opacity,0,f,5);Link(originalUV,0,f,6);Link(edgeStart,0,f,7);Link(edgeEnd,0,f,8);
   foreach(var reference in GraphReflect.List(GraphReflect.Get(GraphReflect.Get(graph,"fragmentContext"),"blocks"))){var block=GraphReflect.Get(reference,"value");string name=GraphReflect.Get(GraphReflect.Get(block,"descriptor"),"name").ToString();if(name=="NormalTS")Link(f,9,block,0);else if(name=="Occlusion")Link(f,10,block,0);else if(name.EndsWith("Alpha"))Link(f,11,block,0);else if(name=="Smoothness")Link(smooth,0,block,0);}
   var json=GraphReflect.Call(GraphReflect.T(SG+"Serialization.MultiJson"),"Serialize",graph).ToString();string path=Root+(pom?"SG_GroundCrack_POM":"DrillCraterDecal")+".shadergraph";File.WriteAllText(path,json);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);
  }
 }
}
